-- Programs: the root resource. Written on every configuration change
-- (config_version / config_hash bump), so it is created with spare room on each
-- page (fillfactor 85): those updates touch no indexed column and stay HOT —
-- no index entries rewritten, no bloat.
--
-- Conventions used by every table in this directory:
--   * `id UUID PRIMARY KEY`, generated by the application as UUIDv7: time-ordered,
--     so new rows append to the right edge of the PK index and the id doubles as
--     the keyset-pagination cursor (`WHERE id > $token ORDER BY id`).
--   * `state TEXT` ('ACTIVE' | 'DELETED') is the AEP-164 soft-delete marker. Uniqueness
--     among live rows is a PARTIAL unique index, so a deleted row never blocks reuse
--     of its key and the index stays small.
--   * Enumerations are plain TEXT validated in the application.
--   * No trigger sets `update_time`: the application does, in the same statement.
--   * Child lists are `WHERE <parent> = $1 AND id > $2 ORDER BY id`, so child tables
--     carry `(parent_id, id)`. Index only what a query needs.
--
-- IDEMPOTENT AND RE-RUNNABLE: the runner keeps no applied-migrations table and
-- replays every `*.up.sql` in filename order, so each statement is a no-op the
-- second time round.
CREATE TABLE IF NOT EXISTS programs (
    id UUID PRIMARY KEY,
    name TEXT NOT NULL,
    slug TEXT NOT NULL,
    description TEXT,
    -- The customer-hierarchy grain the program is anchored at: user | organization | location.
    level TEXT NOT NULL DEFAULT 'location',
    active BOOLEAN NOT NULL DEFAULT true,
    -- Bumped on every configuration change; compared with the latest publication
    -- to detect drift ("unpublished changes").
    config_version INT NOT NULL DEFAULT 1,
    config_hash TEXT NOT NULL DEFAULT '',
    state TEXT NOT NULL DEFAULT 'ACTIVE',
    create_time TIMESTAMPTZ NOT NULL DEFAULT now(),
    update_time TIMESTAMPTZ NOT NULL DEFAULT now()
) WITH (fillfactor = 85);

-- Slug is unique among live programs, case-insensitively; it also serves the
-- `GET /programs/{slug}` lookup.
CREATE UNIQUE INDEX IF NOT EXISTS uq_programs_slug_active_ci
    ON programs (lower(slug)) WHERE state = 'ACTIVE';
CREATE INDEX IF NOT EXISTS idx_programs_active_id
    ON programs (id) WHERE state = 'ACTIVE';
CREATE INDEX IF NOT EXISTS idx_programs_deleted_id
    ON programs (id) WHERE state = 'DELETED';
